--
-- Table structure for table `books`
--

DROP TABLE IF EXISTS `books`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `books` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` char(36) NOT NULL,
  `isbn` varchar(30) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `author` varchar(150) NOT NULL,
  `publisher` varchar(120) NOT NULL DEFAULT 'Sespimma Lemdiklat Polri Press',
  `published_year` smallint(5) unsigned NOT NULL,
  `synopsis` text NOT NULL,
  `library_category_id` varchar(30) NOT NULL,
  `sub_category` varchar(100) DEFAULT NULL,
  `language` enum('Indonesia','Inggris') NOT NULL DEFAULT 'Indonesia',
  `call_number` varchar(50) NOT NULL,
  `physical_location` varchar(150) NOT NULL,
  `stock_total` int(10) unsigned NOT NULL DEFAULT 1,
  `stock_available` int(10) unsigned NOT NULL DEFAULT 1,
  `cover_image_url` varchar(255) DEFAULT NULL,
  `cover_color` varchar(30) DEFAULT '#0d2549',
  `cover_gradient` varchar(120) DEFAULT NULL,
  `lifecycle_status` enum('Draft','Diverifikasi','Dipublikasikan','Tidak Aktif','Arsip') NOT NULL DEFAULT 'Dipublikasikan',
  `access_classification` enum('Terbuka','Internal','Terbatas','Metadata Saja') NOT NULL DEFAULT 'Internal',
  `created_by` bigint(20) unsigned NOT NULL DEFAULT 3,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uuid` (`uuid`),
  KEY `fk_books_creator` (`created_by`),
  KEY `idx_books_category` (`library_category_id`,`stock_available`),
  FULLTEXT KEY `ft_books_search` (`title`,`author`,`synopsis`),
  CONSTRAINT `fk_books_creator` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_books_lib_cat` FOREIGN KEY (`library_category_id`) REFERENCES `library_categories` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4068 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `books`
--

LOCK TABLES `books` WRITE;
/*!40000 ALTER TABLE `books` DISABLE KEYS */;
INSERT INTO `books` VALUES (1,'bk-book-fisik-01','978-623-95841-0-2','Manajemen Logistik dan Pengadaan Polri Modern (Edisi Hardcover Cetak)','AKBP Dewi Susilo Pangestuti, S.Ak. & Tim Ahli Logistik','Sespimma Lemdiklat Polri Press',2025,'Buku referensi cetak komprehensif mengenai tata kelola rantai pasok modern kepolisian, audit kepatuhan pengadaan barang/jasa pemerintah, integrasi Sistem Informasi Manajemen Logistik (SIMLOG), dan standardisasi akuntabilitas aset Barang Milik Negara (BMN) di lingkungan satuan kewilayahan Polri.','buku-fisik','Logistik & Manajemen Aset','Indonesia','658.7 DEW m 2025','Lantai 2, Rak A-04 Perpustakaan Sespimma Lembang',6,4,NULL,'#1e3a8a','linear-gradient(135deg, #0f172a 0%, #1e3a8a 100%)','Dipublikasikan','Internal',3,'2026-11-16 16:55:16','2026-11-16 16:55:16'),(2,'bk-book-fisik-02','978-623-112-401-3','Sosiologi Kepolisian: Manusia, Peradaban, dan Harmoni Kamtibmas (Buku Cetak)','Kompol Heni Mardiyatmi, S.I.P., S.Sos., M.Sc.','Balai Pustaka Lemdiklat Polri',2025,'Kajian mendalam hubungan dialektis antara institusi kepolisian dan dinamika masyarakat majemuk Indonesia. Membedah peran sosiologis perpolisian masyarakat, resolusi sengketa adat, serta pendekatan humaniora dalam menjaga stabilitas keamanan.','buku-fisik','Sosiologi Hukum & Humaniora','Indonesia','301.1 HEN s 2025','Lantai 2, Rak S-02 Perpustakaan Sespimma Lembang',5,3,NULL,'#831843','linear-gradient(135deg, #500724 0%, #831843 100%)','Dipublikasikan','Internal',3,'2026-11-16 16:55:16','2026-11-16 16:55:16'),(3,'bk-book-fisik-03','978-602-53218-9-3','Standar Manajemen Keberhasilan Fungsi Intelkam Polri (Buku Referensi Cetak)','Kombes Pol. Didit Eko Herawanto, S.I.K., S.H.','Intelkam Press & Sespim Lemdiklat',2025,'Standardisasi penyelenggaraan produk intelijen kepolisian, penyusunan Perkiraan Intelijen Khusus (Kirpat), jejaring penyelidikan tertutup, serta sistem deteksi dini (Early Warning System) dalam pengamanan agenda strategis nasional.','buku-fisik','Intelijen & Keamanan Khusus','Indonesia','327.12 DID s 2025','Lantai 2, Rak I-07 Perpustakaan Sespimma Lembang',4,2,NULL,'#334155','linear-gradient(135deg, #0f172a 0%, #334155 100%)','Dipublikasikan','Internal',3,'2026-11-16 16:55:16','2026-11-16 16:55:16'),(4,'bk-book-fisik-04','978-623-01-2894-3','Buku Referensi Hukum: Pembuktian Ilmiah Tindak Pidana Korupsi','Kombes Pol. Dhani Gumilar, S.H., S.I.K., M.H.','Rajawali Pers & Sespimma',2025,'Buku pedoman cetak praktis pembuktian delik korupsi dengan metode forensik akuntansi, audit investigatif kerugian keuangan negara, teknik penelusuran aset (asset tracing), dan penanganan tindak pidana pencucian uang (TPPU).','buku-fisik','Hukum Acara & Tipikor','Indonesia','345.02 DHA p 2025','Lantai 2, Rak H-14 Perpustakaan Sespimma Lembang',5,4,NULL,'#7f1d1d','linear-gradient(135deg, #450a0a 0%, #7f1d1d 100%)','Dipublikasikan','Internal',3,'2026-11-16 16:55:16','2026-11-16 16:55:16'),(5,'bk-book-ebook-01','978-602-53218-4-8','Kepemimpinan Transformasional dan Strategis Kepolisian Abad 21','Irjen Pol. Prof. Dr. Chryshnanda Dwilaksana, M.Si.','Lemdiklat Polri Press (E-Book Edition)',2024,'E-Book resmi yang menelaah secara teoritis dan aplikatif urgensi kepemimpinan transformatif dalam memodernisasi kultur organisasi kepolisian, memperkuat integritas etika personel, serta memimpin reformasi birokrasi berorientasi kepuasan masyarakat.','ebook','Kepemimpinan Strategis','Indonesia','303.34 CHR k 2024 (E)','Koleksi Digital SIPINTAR Cloud Server & Rak E-Book',99,99,NULL,'#b45309','linear-gradient(135deg, #1e293b 0%, #b45309 100%)','Dipublikasikan','Terbuka',3,'2026-11-16 16:55:16','2026-11-16 16:55:16'),(6,'bk-book-ebook-02','978-623-231-892-1','Penegakan Hukum Acara Pidana dan Hak Asasi Manusia (E-Book)','Prof. Dr. Bagus Wicaksono, S.H., LL.M. & Kombes Pol. Hidayat, S.H., S.I.K.','Rajawali Pers & Sespim Lemdiklat Polri',2025,'E-Book kajian komparatif dan doktriner mengenai perlindungan hak asasi manusia dalam setiap tahapan penyidikan pidana, pembaharuan hukum pembuktian ilmiah (scientific crime investigation), standar perlakuan saksi-korban, dan keadilan restoratif.','ebook','Hukum Pidana & HAM','Indonesia','345.05 WIC p 2025 (E)','Koleksi Digital SIPINTAR Cloud Server & Rak H-03',99,99,NULL,'#047857','linear-gradient(135deg, #064e3b 0%, #047857 100%)','Dipublikasikan','Terbuka',3,'2026-11-16 16:55:16','2026-11-16 16:55:16'),(7,'bk-book-ebook-03','978-602-74892-7-5','Investigasi Kejahatan Siber & Pembongkaran Sindikat Judi Online (E-Book)','Tim Siber Bareskrim & Pokja Jarlat Sespimma','Pustaka Ilmu Kepolisian (Digital Edition)',2025,'E-Book materi ajar penyidikan siber mutakhir mengenai pemetaan server dan infrastruktur sindikat judi online ilegal lintas yurisdiksi, penelusuran transaksi kripto (cryptocurrency tracking), serta protokol legal penyitaan bukti digital elektronik.','ebook','Siber & Forensik Digital','Indonesia','364.168 DIN i 2025 (E)','Koleksi Digital SIPINTAR Cloud Server & Rak S-05',99,99,NULL,'#0f766e','linear-gradient(135deg, #134e4a 0%, #0f766e 100%)','Dipublikasikan','Terbuka',3,'2026-11-16 16:55:16','2026-11-18 17:58:11'),(8,'bk-book-ebook-04','978-623-88012-9-1','Inovasi dan Kreatifitas Kepolisian: Akselerasi Smart Policing (E-Book)','Tim Pokja Kurikulum & Gadik Sespimma Lemdiklat Polri','Pustaka Smart Policing (Digital Edition)',2025,'Pedoman implementatif pengembangan pola pikir kreatif dan inovatif bagi perwira kepolisian tingkat menengah. Dilengkapi studi kasus integrasi pelayanan digital terpadu (Smart Policing), Command Center, dan desain inovasi birokrasi Polri.','ebook','Smart Policing & Inovasi','Indonesia','351.74 RAH i 2025 (E)','Koleksi Digital SIPINTAR Cloud Server & Rak I-03',99,99,NULL,'#0284c7','linear-gradient(135deg, #075985 0%, #0284c7 100%)','Dipublikasikan','Terbuka',3,'2026-11-16 16:55:16','2026-11-18 17:58:11'),(9,'bk-book-taskap-01','978-623-95841-1-9','Metodologi Riset Kepolisian & Pedoman Penulisan Taskap Sespimma TA 2026','Pokja Pengembangan Akademik Bag Bangdik Se