LOCK TABLES `resources` WRITE;
/*!40000 ALTER TABLE `resources` DISABLE KEYS */;
INSERT INTO `resources` VALUES (1,'res-hanjar-sespimma-01','Hanjar 01: Peran Polri dalam Optimalisasi Sektor Pangan',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025 mengenai strategi pengawalan, pengamanan terpadu, dan optimalisasi ketahanan pangan nasional.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.29 MB','/1. HANJAR SESPIMMA 2025 PERAN POLRI DALAM OPTIMALISASI SEKTOR PANGAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(2,'res-hanjar-sespimma-02','Hanjar 02: Manajemen Kehumasan Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Strategi komunikasi publik, manajemen media sosial, mitigasi krisis reputasi, dan penguatan transparansi institusi.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.93 MB','/2. HANJAR SESPIMMA 2025 MANAJAMEN KEHUMASAN POLRI.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(3,'res-hanjar-sespimma-03','Hanjar 03: Penanganan Tindak Pidana Narkoba (TP Narkoba)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Taktik penyelidikan peredaran gelap narkotika, clandestine lab, controlled delivery, dan pemutusan jaringan sindikat.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.19 MB','/3. HANJAR SESPIMMA 2025 TP NARKOBA.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(4,'res-hanjar-sespimma-04','Hanjar 04: Penanganan Tindak Pidana Perjudian Online (TP Judol)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Penindakan sindikat judi online lintas-negara, profiling rekening penampung, pemblokiran situs, dan penegakan hukum siber.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.38 MB','/4. HANJAR SESPIMMA 2025 TP JUDOL.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(5,'res-hanjar-sespimma-05','Hanjar 05: Manusia dan Peradaban',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Landasan filosofis, sosiologis, dan kultural hubungan manusia, peradaban hukum, dan pemolisian yang humanis.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Bangdik Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.20 MB','/5. HANJAR SESPIMMA 2025 MANUSIA DAN PERADABAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(6,'res-hanjar-sespimma-06','Hanjar 06: Inovasi dan Kreatifitas Kepolisian',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Metodologi pengembangan inovasi pelayanan publik, creative thinking perwira polri, dan proyek perubahan institusional.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Bangdik Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.24 MB','/6. HANJAR SESPIMMA 2025 INOVASI DAN KREATIFITAS.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(7,'res-hanjar-sespimma-07','Hanjar 07: Penanganan Tindak Pidana Korupsi (TP Korupsi)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Konstruksi hukum tipidkor, audit forensik kerugian keuangan negara, asset recovery, dan koordinasi KPK/Kejaksaan.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.91 MB','/7. HANJAR SESPIMMA 2025 TP KORUPSI.pdf',NULL,1,79,'2026-11-18 00:55:57',NULL,'2025-02-15 08:00:00','2026-11-18 00:55:57'),(8,'res-hanjar-sespimma-08','Hanjar 08: Analisis SWOT dan Analytic Hierarchy Process (AHP)',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Metode analisis kuantitatif dan kualitatif SWOT-AHP dalam perumusan kebijakan strategis dan Taskap perorangan serdik.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Bangdik Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.72 MB','/8. HANJAR SESPIMMA 2025 ANALISIS SWOT DAN AHP.pdf',NULL,1,79,'2026-11-18 00:56:02',NULL,'2025-02-15 08:00:00','2026-11-18 00:56:02'),(9,'res-hanjar-sespimma-09','Hanjar 09: Manajemen Keuangan Satker Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Tata kelola perbendaharaan DIPA, sistem akuntansi instansi, pertanggungjawaban keuangan dinas, dan kepatuhan anggaran.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.92 MB','/9. HANJAR SESPIMMA 2025 MANAJEMEN KEUANGAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(10,'res-hanjar-sespimma-10','Hanjar 10: Manajemen Logistik Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Siklus logistik kepolisian, manajemen pergudangan senpi & amunisi, pemeliharaan randis, dan inventarisasi BMN.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'1.90 MB','/10. HANJAR SESPIMMA 2025 MANAJEMEN LOGISTIK.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(11,'res-hanjar-sespimma-11','Hanjar 11: Penegakan HAM, Hukum, dan Keadilan',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Penerapan prinsip hak asasi manusia dalam tindakan kepolisian, due process of law, dan etika penegakan keadilan.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.05 MB','/11. HANJAR SESPIMMA 2025 PENEGAKAN HAM, HUKUM, DAN KEADILAN.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(12,'res-hanjar-sespimma-12','Hanjar 12: Manajemen & Standar Keberhasilan Fungsi Intelkam',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Tolok ukur keberhasilan operasional intelijen keamanan, deteksi dini kamtibmas, dan penyusunan produk intelijen strategis.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Terbatas',1,'PDF',NULL,'2.00 MB','/12. HANJAR SESPIMMA 2025 MNJMN & STNDR KEBERHASILAN FUNGSI INTELKAM.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(13,'res-hanjar-sespimma-13','Hanjar 13: Manajemen dan Standar Keberhasilan Fungsi Binmas',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Strategi pembinaan masyarakat, kemitraan Polmas, penguatan peran Bhabinkamtibmas, dan pemeliharaan harkamtibmas partisipatif.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.17 MB','/13. HANJAR SESPIMMA 2025 MANAJAMEN DAN STANDAR KEBERHASILAN FUNGSI BINMAS.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(14,'res-hanjar-sespimma-14','Hanjar 14: Manajemen Sumber Daya Manusia (SDM) Polri',2,NULL,'Bahan Ajar Pokok (2025)','Bahan ajar resmi Sespimma Lemdiklat Polri TA 2025: Siklus pembinaan personel polri, penilaian kinerja berbasis 13 komponen, asesmen kompetensi, dan penegakan meritokrasi.','Tim Pokja Hanjar Sespimma Lemdiklat Polri','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'2.30 MB','/14. HANJAR SESPIMMA 2025 MANAJEMEN SDM.pdf',NULL,1,2,'2025-02-15 08:00:00',NULL,'2025-02-15 08:00:00','2026-11-16 16:55:16'),(15,'res-001','Hanjar Kepemimpinan Strategis Polri Modern di Era Digital',2,NULL,'Bahan Ajar Pokok','Materi pedoman implementasi strategi pemolisian visioner berbasis data dan integritas organisasi.','Kombes Pol. Dr. Hendra Pratama, S.I.K., M.Si.','Bag Jarlat Sespimma Lemdiklat Polri','Dipublikasikan','Internal',1,'PDF',NULL,'4.8 MB',NULL,NULL,1,2,'2026-09-18 08:00:00',NULL,'2026-09-18 08:00:00','2026-11-16 16:55:16'),(16,'book-fisik-01','Manajemen Logistik dan Pengadaan Polri Modern (Edisi Hardcover Cetak)',3,NULL,'Koleksi Buku Fisik','Buku referensi cetak komprehensif mengenai tata kelola rantai pasok modern kepolisian, audit kepatuhan pengadaan barang/jasa pemerintah, integrasi Sistem Informasi Manajemen Logistik (SIMLOG), dan standardisasi akuntabilitas aset Barang Milik Negara (BMN) di lingkungan satuan kewilayahan Polri.','AKBP Dewi Susilo Pangestuti, S.Ak. & Tim Ahli Logistik','Sespimma Lemdiklat Polri Press','Dipublikasikan','Terbuka',1,'PDF',NULL,'1.99 MB','/10. HANJAR SESPIMMA 2025 MANAJEMEN LOGISTIK.pdf','Lantai 2, Rak A-04 Perpustakaan Sespimma Lembang',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(17,'book-fisik-02','Sosiologi Kepolisian: Manusia, Peradaban, dan Harmoni Kamtibmas (Buku Cetak)',3,NULL,'Koleksi Buku Fisik','Kajian mendalam hubungan dialektis antara institusi kepolisian dan dinamika masyarakat majemuk Indonesia. Membedah peran sosiologis perpolisian masyarakat, resolusi sengketa adat, serta pendekatan humaniora dalam menjaga stabilitas keamanan.','Kompol Heni Mardiyatmi, S.I.P., S.Sos., M.Sc.','Balai Pustaka Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.31 MB','/5. HANJAR SESPIMMA 2025 MANUSIA DAN PERADABAN.pdf','Lantai 2, Rak S-02 Perpustakaan Sespimma Lembang',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(18,'book-fisik-03','Standar Manajemen Keberhasilan Fungsi Intelkam Polri (Buku Referensi Cetak)',3,NULL,'Koleksi Buku Fisik','Standardisasi penyelenggaraan produk intelijen kepolisian, penyusunan Perkiraan Intelijen Khusus (Kirpat), jejaring penyelidikan tertutup, serta sistem deteksi dini (Early Warning System) dalam pengamanan agenda strategis nasional.','Kombes Pol. Didit Eko Herawanto, S.I.K., S.H.','Intelkam Press & Sespim Lemdiklat','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.09 MB','/12. HANJAR SESPIMMA 2025 MNJMN & STNDR KEBERHASILAN FUNGSI INTELKAM.pdf','Lantai 2, Rak I-07 Perpustakaan Sespimma Lembang',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(19,'book-fisik-04','Buku Referensi Hukum: Pembuktian Ilmiah Tindak Pidana Korupsi',3,NULL,'Koleksi Buku Fisik','Buku pedoman cetak praktis pembuktian delik korupsi dengan metode forensik akuntansi, audit investigatif kerugian keuangan negara, teknik penelusuran aset (asset tracing), dan penanganan tindak pidana pencucian uang (TPPU).','Kombes Pol. Dhani Gumilar, S.H., S.I.K., M.H.','Rajawali Pers & Sespimma','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.00 MB','/7. HANJAR SESPIMMA 2025 TP KORUPSI.pdf','Lantai 2, Rak H-14 Perpustakaan Sespimma Lembang',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(20,'book-ebook-01','Kepemimpinan Transformasional dan Strategis Kepolisian Abad 21',3,NULL,'E-Book','E-Book resmi yang menelaah secara teoritis dan aplikatif urgensi kepemimpinan transformatif dalam memodernisasi kultur organisasi kepolisian, memperkuat integritas etika personel, serta memimpin reformasi birokrasi berorientasi kepuasan masyarakat.','Irjen Pol. Prof. Dr. Chryshnanda Dwilaksana, M.Si.','Lemdiklat Polri Press (E-Book Edition)','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.39 MB','/1. HANJAR SESPIMMA 2025 PERAN POLRI DALAM OPTIMALISASI SEKTOR PANGAN.pdf','Koleksi Digital SIPINTAR Cloud Server & Rak E-Book',1,2,'2024-10-01 08:00:00',NULL,'2024-10-01 08:00:00','2026-11-16 16:55:16'),(21,'book-ebook-02','Penegakan Hukum Acara Pidana dan Hak Asasi Manusia (E-Book)',3,NULL,'E-Book','E-Book kajian komparatif dan doktriner mengenai perlindungan hak asasi manusia dalam setiap tahapan penyidikan pidana, pembaharuan hukum pembuktian ilmiah (scientific crime investigation), standar perlakuan saksi-korban, dan keadilan restoratif.','Prof. Dr. Bagus Wicaksono, S.H., LL.M. & Kombes Pol. Hidayat, S.H., S.I.K.','Rajawali Pers & Sespim Lemdiklat Polri','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.14 MB','/11. HANJAR SESPIMMA 2025 PENEGAKAN HAM, HUKUM, DAN KEADILAN.pdf','Koleksi Digital SIPINTAR Cloud Server & Rak H-03',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(22,'book-ebook-03','Investigasi Kejahatan Siber & Pembongkaran Sindikat Judi Online (E-Book)',3,NULL,'E-Book','E-Book materi ajar penyidikan siber mutakhir mengenai pemetaan server dan infrastruktur sindikat judi online ilegal lintas yurisdiksi, penelusuran transaksi kripto (cryptocurrency tracking), serta protokol legal penyitaan bukti digital elektronik.','Tim Siber Bareskrim & Pokja Jarlat Sespimma','Pustaka Ilmu Kepolisian (Digital Edition)','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.49 MB','/4. HANJAR SESPIMMA 2025 TP JUDOL.pdf','Koleksi Digital SIPINTAR Cloud Server & Rak S-05',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-18 17:58:11'),(23,'book-ebook-04','Inovasi dan Kreatifitas Kepolisian: Akselerasi Smart Policing (E-Book)',3,NULL,'E-Book','Pedoman implementatif pengembangan pola pikir kreatif dan inovatif bagi perwira kepolisian tingkat menengah. Dilengkapi studi kasus integrasi pelayanan digital terpadu (Smart Policing), Command Center, dan desain inovasi birokrasi Polri.','Tim Pokja Kurikulum & Gadik Sespimma Lemdiklat Polri','Pustaka Smart Policing (Digital Edition)','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.35 MB','/6. HANJAR SESPIMMA 2025 INOVASI DAN KREATIFITAS.pdf','Koleksi Digital SIPINTAR Cloud Server & Rak I-03',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-18 17:58:11'),(24,'book-taskap-01','Metodologi Riset Kepolisian & Pedoman Penulisan Taskap Sespimma TA 2026',3,NULL,'Karya Tulis Kepolisian (Taskap)','Pedoman teknis baku perumusan judul, kerangka berpikir analitis, metodologi riset kepolisian terapan, teknik analisis data menggunakan SWOT dan Analytic Hierarchy Process (AHP), serta format sitasi ilmiah karya tulis perorangan Serdik.','Pokja Pengembangan Akademik Bag Bangdik Sespimma','Sespimma Press (Arsip Akademik)','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.85 MB','/8. HANJAR SESPIMMA 2025 ANALISIS SWOT DAN AHP.pdf','Lantai 1, Ruang Khusus Taskap Lemari C-02',1,2,'2026-10-01 08:00:00',NULL,'2026-10-01 08:00:00','2026-11-16 16:55:16'),(25,'book-taskap-02','Taskap: Optimalisasi Pelayanan Publik Terpadu Berbasis AI di Tingkat Polres',3,NULL,'Karya Tulis Kepolisian (Taskap)','Kertas Karya Perorangan (Taskap) peserta didik Sespimma yang merumuskan arsitektur kecerdasan buatan untuk mengotomatisasi penerbitan SKCK, pemantauan pengaduan masyarakat Propam, dan penjadwalan patroli presisi berbasis heat map kriminalitas.','Kompol Arya Ramadhan, S.I.K. (Serdik Sespimma Angkatan 66)','Subbag Renmin Bag Jarlat Sespimma','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.35 MB','/6. HANJAR SESPIMMA 2025 INOVASI DAN KREATIFITAS.pdf','Lantai 1, Ruang Khusus Arsip Taskap Rak A-02',1,2,'2026-10-01 08:00:00',NULL,'2026-10-01 08:00:00','2026-11-16 16:55:16'),(26,'book-taskap-03','Taskap: Manajemen Konflik Sosial dan Resolusi Sengketa Agraria Komunal',3,NULL,'Karya Tulis Kepolisian (Taskap)','Karya tulis perorangan predikat naskah terbaik Sespimma mengenai model mediasi kolaboratif antara aparat kepolisian, instansi pertanahan (BPN), dan perwakilan masyarakat adat guna memitigasi eskalasi konflik fisik pertanahan.','Kompol Dian Wardhana, S.H., S.I.K. (Serdik Sespimma Angkatan 65)','Perpustakaan Sespimma (Koleksi Taskap Terpilih)','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.27 MB','/13. HANJAR SESPIMMA 2025 MANAJAMEN DAN STANDAR KEBERHASILAN FUNGSI BINMAS.pdf','Lantai 1, Ruang Khusus Arsip Taskap Rak B-01',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(27,'book-jurnal-01','Jurnal Ilmu Kepolisian & Strategi Keamanan Sespimma (Edisi TA 2026)',3,NULL,'Jurnal Ilmiah Terbitan','Terbitan berkala ilmiah terakreditasi memuat artikel hasil riset empiris tenaga pendidik (Gadik) dan perwira Polri mengenai efektivitas community policing, transformasi digital manajemen penyidikan, dan evaluasi kurikulum kepemimpinan.','Dewan Redaksi Jurnal Ilmiah Sespim Lemdiklat Polri','Sespimma Lemdiklat Polri Press','Dipublikasikan','Terbuka',1,'PDF',NULL,'139.7 KB','/NOMINATIF%20POLRI%20(FUNGSIONAL)%20BLN%20OKTOBER%202026%20.pdf','Lantai 2, Rak Terbitan Berkala & Jurnal J-01',1,2,'2026-10-01 08:00:00',NULL,'2026-10-01 08:00:00','2026-11-16 16:55:16'),(28,'book-jurnal-02','Jurnal Transformasi Manajemen & Kepemimpinan Publik Polri (Edisi 2025)',3,NULL,'Jurnal Ilmiah Terbitan','Publikasi ilmiah berkala yang membedah kepemimpinan adaptif dalam pengelolaan SDM Polri berbasis meritokrasi, tata kelola pengadaan barang logistik, dan akuntabilitas keuangan negara di lingkungan kepolisian.','Tim Redaksi Jurnal Manajemen Sespim Lemdiklat','Lemdiklat Polri Press','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.41 MB','/14. HANJAR SESPIMMA 2025 MANAJEMEN SDM.pdf','Lantai 2, Rak Terbitan Berkala & Jurnal J-02',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(29,'book-jurnal-03','Jurnal Komunikasi Publik & Mitigasi Krisis Kehumasan Polri (2025)',3,NULL,'Jurnal Ilmiah Terbitan','Kumpulan artikel ilmiah empiris mengenai manajemen isu kontroversial di media massa, penanganan hoaks kamtibmas, serta efektivitas komunikasi institusi Polri dalam membangun kepercayaan publik (public trust).','Pusat Studi Komunikasi Strategis Sespim Lemdiklat','Divisi Humas & Sespim Lemdiklat','Dipublikasikan','Terbuka',1,'PDF',NULL,'2.02 MB','/2. HANJAR SESPIMMA 2025 MANAJAMEN KEHUMASAN POLRI.pdf','Lantai 2, Rak Terbitan Berkala & Jurnal J-03',1,2,'2025-10-01 08:00:00',NULL,'2025-10-01 08:00:00','2026-11-16 16:55:16'),(30,'res-004','SOP Penyelenggaraan Evaluasi Akademik dan Sidang Kertas Karya Perorangan',5,NULL,'Standar Operasional Prosedur','Ketentuan baku tata cara pelaksanaan ujian komprehensif dan sidang pleno kelulusan