/*!40000 ALTER TABLE `user_profiles_gadik` DISABLE KEYS */;
INSERT INTO `user_profiles_gadik` VALUES (7,1,'KOMBES POL','ANJAK MADYA SESPIMMA','Anjak Madya','ISLAM','II B3','IV-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Perwira Menengah Polri berpangkat Kombes Pol dengan penugasan sebagai Analis Kebijakan Madya (Anjak Madya) Sespimma Sespim Lemdiklat Polri. Berpengalaman luas dalam perencanaan strategis kepolisian dan pembimbingan Taskap.'),(8,2,'KOMBES POL','WIDYA ISWARA KEPOLISIAN MADYA TK. III SESPIMMA SESPIM LEMDIKLAT POLRI','Widyaiswara Madya Tk. III','ISLAM','II B3','IV-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Madya Tingkat III Sespimma Sespim Lemdiklat Polri. Berpengalaman dalam pengembangan kepemimpinan kepolisian berkarakter presisi dan adaptif.'),(9,3,'KOMBES POL','WIDYA ISWARA KEPOLISIAN MADYA TK. III SESPIMMA SESPIM LEMDIKLAT POLRI','Widyaiswara Madya Tk. III','ISLAM','II B3','IV-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Madya Tingkat III spesialisasi hukum dan hak asasi manusia. Mengampu mata kuliah penegakan hukum berkeadilan dan penerapan keadilan restoratif.'),(10,4,'KOMBES POL','WIDYA ISWARA KEPOLISIAN MADYA TK. III SESPIMMA SESPIM LEMDIKLAT POLRI','Widyaiswara Madya Tk. III','KRISTEN','II B3','IV-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Madya Tingkat III dengan kepakaran mendalam di bidang strategi kehumasan institusi, mitigasi krisis komunikasi publik, dan literasi media.'),(11,5,'KOMBES POL','WIDYA ISWARA KEPOLISIAN MADYA TK. III SESPIMMA SESPIM LEMDIKLAT POLRI','Widyaiswara Madya Tk. III','ISLAM','II B3','IV-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Madya Tingkat III berpengalaman dalam penyidikan tindak pidana korupsi dan narkoba tingkat lanjut serta penelusuran aset kejahatan kerah putih.'),(12,6,'KOMBES POL','WIDYA ISWARA KEPOLISIAN MADYA TK. III SESPIMMA SESPIM LEMDIKLAT POLRI','Widyaiswara Madya Tk. III','ISLAM','II B3','IV-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Madya Tingkat III pakar di bidang intelijen kepolisian, deteksi dini ancaman kamtibmas, dan manajemen perkiraan intelijen kontinjensi.'),(13,7,'AKBP','GADIK MADYA SESPIMMA','Gadik Madya','ISLAM','III A2','IV-B','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Tenaga Pendidik Madya (Gadik Madya) Sespimma dengan kepakaran pada manajemen SDM unggul Polri, sistem penilaian kinerja berbasis kompetensi, dan psikologi organisasi.'),(14,8,'AKBP','GADIK MADYA SESPIMMA','Gadik Madya','ISLAM','III A2','IV-B','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Tenaga Pendidik Madya (Gadik Madya) Sespimma Lemdiklat Polri sekaligus Inovator Utama Sistem Informasi Pembelajaran Terpadu SIPINTAR (Proyek Perubahan PKN Tingkat II Angkatan XXIX TA 2026). Pakar manajemen logistik dan akuntansi kepolisian.'),(15,9,'AKBP','GADIK MADYA SESPIMMA','Gadik Madya','ISLAM','III A2','IV-B','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Tenaga Pendidik Madya (Gadik Madya) Sespimma bidang analisis kebijakan kuantitatif dan kualitatif. Menguasai pemodelan keputusan berjenjang (AHP) dan perumusan strategi pemecahan masalah institusi.'),(19,13,'KOMPOL','WIDYAISWARA KEPOLISIAN MUDA TK. I SESPIMMA','Widyaiswara Muda Tk. I','ISLAM','III A2','IV-A','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Muda Tingkat I dengan latar belakang multidisiplin ilmu sosial dan kebijakan publik, mengampu modul pemahaman peradaban manusia serta pendekatan humanis kepolisian.'),(21,15,'KOMPOL','WIDYAISWARA KEPOLISIAN MUDA TK. I SESPIMMA','Widyaiswara Muda Tk. I','ISLAM','III B','III-C','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Muda Tingkat I dengan rekam jejak pada pengawasan internal kepolisian, penegakan disiplin anggota, dan standarisasi proses penyidikan berkeadilan.'),(22,16,'IPTU','WIDYAISWARA KEPOLISIAN PRATAMA TK. I SESPIMMA','Widyaiswara Pratama Tk. I','ISLAM','IV B','III-B','Aktif Fungsional','Sprin/128/X/DIK.2.1./2026','Widyaiswara Kepolisian Pratama Tingkat I dengan keahlian teknis hukum pidana acara, simulasi peradilan semu (moot court), serta pendampingan advokasi hukum institusi.');
/*!40000 ALTER TABLE `user_profiles_gadik` ENABLE KEYS */;
UNLOCK TABLES;

